def can_finish_brute(num_courses, prerequisites):
    requires = [[] for _ in range(num_courses)]
    for after, before in prerequisites:
        requires[after].append(before)
    remaining = set(range(num_courses))
    while remaining:
        ready = [c for c in remaining
                 if all(b not in remaining for b in requires[c])]
        if not ready:
            return False
        for course in ready:
            remaining.discard(course)
    return True


