import java.util.*;

public class Main {
    public static void main(String[] args) {
        int numCourses = 4;
        int[][] prerequisites = {{1, 0}, {2, 0}, {3, 1}, {3, 2}};
        System.out.println(canFinishBrute(numCourses, prerequisites));
    }

    public static boolean canFinishBrute(int numCourses, int[][] prerequisites) {
        List<List<Integer>> requires = new ArrayList<>();
        for (int i = 0; i < numCourses; i++) requires.add(new ArrayList<>());
        for (int[] p : prerequisites) requires.get(p[0]).add(p[1]);
        Set<Integer> remaining = new HashSet<>();
        for (int i = 0; i < numCourses; i++) remaining.add(i);
        while (!remaining.isEmpty()) {
            List<Integer> ready = new ArrayList<>();
            for (int c : remaining) {
                boolean allDone = true;
                for (int b : requires.get(c)) {
                    if (remaining.contains(b)) { allDone = false; break; }
                }
                if (allDone) ready.add(c);
            }
            if (ready.isEmpty()) return false;
            remaining.removeAll(ready);
        }
        return true;
    }
}

