        int[] nums = {2, 7, 9, 3, 1};
        System.out.println(robMemo(nums));
    }

    public static int robMemo(int[] nums) {
        int[] memo = new int[nums.length];
        Arrays.fill(memo, -1);
        return memoHelper(nums, 0, memo);
    }

    private static int memoHelper(int[] nums, int index, int[] memo) {
        if (index >= nums.length) return 0;
        if (memo[index] != -1) return memo[index];
        int take = nums[index] + memoHelper(nums, index + 2, memo);
        int skip = memoHelper(nums, index + 1, memo);
        memo[index] = Math.max(take, skip);
        return memo[index];
    }
}

