    }

    public static int robDp(int[] nums) {
        int prev2 = 0;
        int prev1 = 0;
        for (int money : nums) {
            int current = Math.max(prev1, prev2 + money);
            prev2 = prev1;
            prev1 = current;
        }
        return prev1;
    }
}

