def min_window_brute(s, t):
    n = len(s)
    best_start, best_len = 0, n + 1
    for i in range(n):
        for j in range(i + 1, n + 1):
            need = {}
            for ch in t:
                need[ch] = need.get(ch, 0) + 1
            for k in range(i, j):
                ch = s[k]
                if ch in need:
                    need[ch] -= 1
            if all(v <= 0 for v in need.values()) and j - i < best_len:
                best_start, best_len = i, j - i
    return "" if best_len == n + 1 else s[best_start:best_start + best_len]


