import java.util.*;

public class Main {
    public static void main(String[] args) {
        String s = "ADOBECODEBANC";
        String t = "ABC";
        System.out.println(minWindowBrute(s, t));
    }

    public static String minWindowBrute(String s, String t) {
        int bestStart = 0;
        int bestLen = s.length() + 1;
        for (int i = 0; i < s.length(); i++) {
            for (int j = i + 1; j <= s.length(); j++) {
                if (j - i < bestLen && containsAll(s, i, j, t)) {
                    bestStart = i;
                    bestLen = j - i;
                }
            }
        }
        return bestLen == s.length() + 1 ? "" : s.substring(bestStart, bestStart + bestLen);
    }

    private static boolean containsAll(String s, int start, int end, String t) {
        int[] need = new int[128];
        for (char c : t.toCharArray()) need[c]++;
        for (int k = start; k < end; k++) {
            need[s.charAt(k)]--;
        }
        for (int v : need) if (v > 0) return false;
        return true;
    }
}

