import java.util.*;

public class Main {
    public static void main(String[] args) {
        String beginWord = "hit";
        String endWord = "cog";
        List<String> wordList = Arrays.asList("hot", "dot", "dog", "lot", "log", "cog");
        System.out.println(ladderLengthBrute(beginWord, endWord, wordList));
    }

    public static int ladderLengthBrute(String beginWord, String endWord, List<String> wordList) {
        Set<String> words = new HashSet<>(wordList);
        if (!words.contains(endWord)) return 0;
        Queue<String> queue = new LinkedList<>();
        Map<String, Integer> depth = new HashMap<>();
        queue.add(beginWord);
        depth.put(beginWord, 1);
        while (!queue.isEmpty()) {
            String word = queue.poll();
            int d = depth.get(word);
            if (word.equals(endWord)) return d;
            for (String candidate : words) {
                if (!depth.containsKey(candidate) && adjacent(word, candidate)) {
                    depth.put(candidate, d + 1);
                    queue.add(candidate);
                }
            }
        }
        return 0;
    }

    private static boolean adjacent(String a, String b) {
        int diff = 0;
        for (int i = 0; i < a.length(); i++) {
            if (a.charAt(i) != b.charAt(i)) diff++;
        }
        return diff == 1;
    }
}

