import java.util.*;

public class Main {
    public static void main(String[] args) {
        String beginWord = "hit";
        String endWord = "cog";
        List<String> wordList = Arrays.asList("hot", "dot", "dog", "lot", "log", "cog");
        System.out.println(ladderLengthPattern(beginWord, endWord, wordList));
    }

    public static int ladderLengthPattern(String beginWord, String endWord, List<String> wordList) {
        Set<String> words = new HashSet<>(wordList);
        if (!words.contains(endWord)) return 0;
        Map<String, List<String>> patternMap = new HashMap<>();
        for (String w : words) {
            for (int i = 0; i < w.length(); i++) {
                String pattern = w.substring(0, i) + "*" + w.substring(i + 1);
                patternMap.computeIfAbsent(pattern, k -> new ArrayList<>()).add(w);
            }
        }
        Queue<String> queue = new LinkedList<>();
        Map<String, Integer> depth = new HashMap<>();
        queue.add(beginWord);
        depth.put(beginWord, 1);
        while (!queue.isEmpty()) {
            String word = queue.poll();
            int d = depth.get(word);
            if (word.equals(endWord)) return d;
            for (int i = 0; i < word.length(); i++) {
                String pattern = word.substring(0, i) + "*" + word.substring(i + 1);
                for (String nxt : patternMap.getOrDefault(pattern, Collections.emptyList())) {
                    if (!depth.containsKey(nxt)) {
                        depth.put(nxt, d + 1);
                        queue.add(nxt);
                    }
                }
            }
        }
        return 0;
    }
}

