        String beginWord = "hit";
        String endWord = "cog";
        List<String> wordList = Arrays.asList("hot", "dot", "dog", "lot", "log", "cog");
        System.out.println(ladderLengthBidirectional(beginWord, endWord, wordList));
    }

    public static int ladderLengthBidirectional(String beginWord, String endWord, List<String> wordList) {
        Set<String> words = new HashSet<>(wordList);
        if (!words.contains(endWord)) return 0;
        Set<String> front = new HashSet<>();
        Set<String> back = new HashSet<>();
        front.add(beginWord);
        back.add(endWord);
        Set<String> visitedFront = new HashSet<>(front);
        Set<String> visitedBack = new HashSet<>(back);
        int depth = 1;
        while (!front.isEmpty()) {
            if (front.size() > back.size()) {
                Set<String> tmp = front; front = back; back = tmp;
                tmp = visitedFront; visitedFront = visitedBack; visitedBack = tmp;
            }
            Set<String> next = new HashSet<>();
            for (String word : front) {
                char[] arr = word.toCharArray();
                for (int i = 0; i < arr.length; i++) {
                    char original = arr[i];
                    for (char c = 'a'; c <= 'z'; c++) {
                        if (c == original) continue;
                        arr[i] = c;
                        String candidate = new String(arr);
                        if (back.contains(candidate)) return depth + 1;
                        if (words.contains(candidate) && !visitedFront.contains(candidate)) {
                            visitedFront.add(candidate);
                            next.add(candidate);
                        }
                    }
                    arr[i] = original;
                }
            }
            front = next;
            depth++;
        }
        return 0;
    }
