def full_justify_rec(words, max_width):
    def pack(start):
        length = 0
        end = start
        while end < len(words):
            add = len(words[end]) + (1 if end > start else 0)
            if length + add > max_width:
                break
            length += add
            end += 1
        return end

    def justify_line(start, end, is_last):
        line = words[start:end]
        if is_last or len(line) == 1:
            text = " ".join(line)
            return text + " " * (max_width - len(text))
        total_spaces = max_width - sum(len(w) for w in line)
        gaps = len(line) - 1
        base, extra = divmod(total_spaces, gaps)
        out = []
        for j, word in enumerate(line):
            out.append(word)
            if j < gaps:
                out.append(" " * (base + (1 if j < extra else 0)))
        return "".join(out)

    def build(start):
        if start >= len(words):
            return []
        end = pack(start)
        is_last = end >= len(words)
        return [justify_line(start, end, is_last)] + build(end)

    return build(0)


