        return build(words, 0, maxWidth);
    }

    private static List<String> build(String[] words, int start, int maxWidth) {
        if (start >= words.length) return new ArrayList<>();
        int end = pack(words, start, maxWidth);
        boolean isLast = end >= words.length;
        String line = justifyLine(words, start, end, isLast, maxWidth);
        List<String> result = new ArrayList<>();
        result.add(line);
        result.addAll(build(words, end, maxWidth));
        return result;
    }

    private static int pack(String[] words, int start, int maxWidth) {
        int length = 0;
        int end = start;
        while (end < words.length) {
            int add = words[end].length() + (end > start ? 1 : 0);
            if (length + add > maxWidth) break;
            length += add;
            end++;
        }
        return end;
    }

    private static String justifyLine(String[] words, int start, int end, boolean isLast, int maxWidth) {
        int letters = 0;
        for (int k = start; k < end; k++) letters += words[k].length();
        int gaps = end - start - 1;
        StringBuilder sb = new StringBuilder();
        if (isLast || gaps == 0) {
            for (int k = start; k < end; k++) {
                if (k > start) sb.append(' ');
                sb.append(words[k]);
            }
            while (sb.length() < maxWidth) sb.append(' ');
            return sb.toString();
        }
        int totalSpaces = maxWidth - letters;
        int base = totalSpaces / gaps;
        int extra = totalSpaces % gaps;
        for (int k = start; k < end; k++) {
            sb.append(words[k]);
            if (k - start < gaps) {
                for (int s = 0; s < base + (k - start < extra ? 1 : 0); s++) sb.append(' ');
            }
        }
        return sb.toString();
    }
}

