import java.util.*;

public class Main {
    public static void main(String[] args) {
        String s = " 3+5/2 ";
        System.out.println(calculateTwoStacks(s));
    }

    public static int calculateTwoStacks(String s) {
        Deque<Integer> numbers = new ArrayDeque<>();
        Deque<Character> operators = new ArrayDeque<>();
        int i = 0;
        int n = s.length();
        while (i < n) {
            char ch = s.charAt(i);
            if (ch == ' ') {
                i++;
            } else if (Character.isDigit(ch)) {
                int num = 0;
                while (i < n && Character.isDigit(s.charAt(i))) {
                    num = num * 10 + (s.charAt(i) - '0');
                    i++;
                }
                numbers.push(num);
            } else {
                while (!operators.isEmpty() && precedence(operators.peek()) >= precedence(ch)) {
                    apply(numbers, operators);
                }
                operators.push(ch);
                i++;
            }
        }
        while (!operators.isEmpty()) apply(numbers, operators);
        return numbers.pop();
    }

    private static int precedence(char op) {
        return (op == '+' || op == '-') ? 1 : 2;
    }

    private static void apply(Deque<Integer> numbers, Deque<Character> operators) {
        int b = numbers.pop();
        int a = numbers.pop();
        char op = operators.pop();
        switch (op) {
            case '+': numbers.push(a + b); break;
            case '-': numbers.push(a - b); break;
            case '*': numbers.push(a * b); break;
            default: numbers.push(a / b);
        }
    }
}

