        int[] nums = {1, 2, 3};
        System.out.println(Arrays.toString(nextPermutationBrute(nums)));
    }

    public static int[] nextPermutationBrute(int[] nums) {
        List<int[]> perms = new ArrayList<>();
        int[] values = nums.clone();
        Arrays.sort(values);
        permute(values, 0, perms);
        perms.sort((a, b) -> Arrays.compare(a, b));
        for (int i = 0; i < perms.size(); i++) {
            if (Arrays.equals(perms.get(i), nums)) {
                return perms.get((i + 1) % perms.size());
            }
        }
        return nums.clone();
    }

    private static void permute(int[] values, int start, List<int[]> out) {
        if (start == values.length) {
            out.add(values.clone());
            return;
        }
        Set<Integer> seen = new HashSet<>();
        for (int i = start; i < values.length; i++) {
            if (seen.contains(values[i])) continue;
            seen.add(values[i]);
            swap(values, start, i);
            permute(values, start + 1, out);
            swap(values, start, i);
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int t = arr[i];
        arr[i] = arr[j];
        arr[j] = t;
    }
}

