        System.out.println(Arrays.toString(nextPermutationGen(nums)));
    }

    public static int[] nextPermutationGen(int[] nums) {
        int[] values = nums.clone();
        Arrays.sort(values);
        boolean[] used = new boolean[values.length];
        boolean[] found = {false};
        List<int[]> out = new ArrayList<>();
        int[] path = new int[values.length];
        backtrack(values, used, path, 0, nums.clone(), found, out);
        if (out.isEmpty()) return values;
        return out.get(0);
    }

    private static boolean backtrack(int[] values, boolean[] used, int[] path, int depth,
                                     int[] target, boolean[] found, List<int[]> out) {
        if (depth == values.length) {
            if (found[0]) {
                out.add(path.clone());
                return true;
            }
            if (Arrays.equals(path, target)) found[0] = true;
            return false;
        }
        for (int i = 0; i < values.length; i++) {
            if (used[i]) continue;
            if (i > 0 && values[i] == values[i - 1] && !used[i - 1]) continue;
            used[i] = true;
            path[depth] = values[i];
            if (backtrack(values, used, path, depth + 1, target, found, out)) return true;
            used[i] = false;
        }
        return false;
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        int[] nums = {1, 2, 3};
        System.out.println(Arrays.toString(nextPermutationInplace(nums)));
    }

    public static int[] nextPermutationInplace(int[] nums) {
        int n = nums.length;
        int i = n - 2;
        while (i >= 0 && nums[i] >= nums[i + 1]) i--;
        if (i >= 0) {
            int j = n - 1;
            while (nums[j] <= nums[i]) j--;
            int temp = nums[i];
            nums[i] = nums[j];
            nums[j] = temp;
        }
        int left = i + 1;
        int right = n - 1;
        while (left < right) {
            int temp = nums[left];
            nums[left] = nums[right];
            nums[right] = temp;
            left++;
            right--;
        }
        return nums;
    }
}

