        System.out.println(Arrays.toString(findOrderBrute(numCourses, prerequisites)));
    }

    public static int[] findOrderBrute(int numCourses, int[][] prerequisites) {
        List<List<Integer>> requires = new ArrayList<>();
        for (int i = 0; i < numCourses; i++) requires.add(new ArrayList<>());
        for (int[] p : prerequisites) requires.get(p[0]).add(p[1]);
        Set<Integer> remaining = new HashSet<>();
        for (int i = 0; i < numCourses; i++) remaining.add(i);
        List<Integer> order = new ArrayList<>();
        while (!remaining.isEmpty()) {
            int ready = -1;
            for (int c : remaining) {
                boolean allDone = true;
                for (int b : requires.get(c)) {
                    if (remaining.contains(b)) { allDone = false; break; }
                }
                if (allDone) { ready = c; break; }
            }
            if (ready == -1) return new int[0];
            remaining.remove(ready);
            order.add(ready);
        }
        int[] result = new int[order.size()];
        for (int i = 0; i < order.size(); i++) result[i] = order.get(i);
        return result;
    }
}

