def find_order_dfs(num_courses, prerequisites):
    graph = [[] for _ in range(num_courses)]
    for after, before in prerequisites:
        graph[before].append(after)
    state = [0] * num_courses  # 0 unvisited, 1 visiting, 2 done
    order = []

    def visit(node):
        if state[node] == 1:
            return False
        if state[node] == 2:
            return True
        state[node] = 1
        for nxt in graph[node]:
            if not visit(nxt):
                return False
        state[node] = 2
        order.append(node)
        return True

    for course in range(num_courses):
        if not visit(course):
            return []
    return order[::-1]


