import java.util.*;

public class Main {
    public static void main(String[] args) {
        int numCourses = 4;
        int[][] prerequisites = {{1, 0}, {2, 0}, {3, 1}, {3, 2}};
        System.out.println(Arrays.toString(findOrderDfs(numCourses, prerequisites)));
    }

    public static int[] findOrderDfs(int numCourses, int[][] prerequisites) {
        List<List<Integer>> graph = new ArrayList<>();
        for (int i = 0; i < numCourses; i++) graph.add(new ArrayList<>());
        for (int[] p : prerequisites) graph.get(p[1]).add(p[0]);
        int[] state = new int[numCourses];
        List<Integer> order = new ArrayList<>();
        for (int c = 0; c < numCourses; c++) {
            if (!visit(c, graph, state, order)) return new int[0];
        }
        Collections.reverse(order);
        int[] result = new int[numCourses];
        for (int i = 0; i < numCourses; i++) result[i] = order.get(i);
        return result;
    }

    private static boolean visit(int node, List<List<Integer>> graph, int[] state, List<Integer> order) {
        if (state[node] == 1) return false;
        if (state[node] == 2) return true;
        state[node] = 1;
        for (int nxt : graph.get(node)) {
            if (!visit(nxt, graph, state, order)) return false;
        }
        state[node] = 2;
        order.add(node);
        return true;
    }
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        int numCourses = 4;
        int[][] prerequisites = {{1, 0}, {2, 0}, {3, 1}, {3, 2}};
        System.out.println(Arrays.toString(findOrderKahn(numCourses, prerequisites)));
    }

    public static int[] findOrderKahn(int numCourses, int[][] prerequisites) {
        List<List<Integer>> graph = new ArrayList<>();
        int[] indegree = new int[numCourses];
        for (int i = 0; i < numCourses; i++) graph.add(new ArrayList<>());
        for (int[] p : prerequisites) {
            graph.get(p[1]).add(p[0]);
            indegree[p[0]]++;
        }
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < numCourses; i++) {
            if (indegree[i] == 0) queue.add(i);
        }
        List<Integer> order = new ArrayList<>();
        while (!queue.isEmpty()) {
            int course = queue.poll();
            order.add(course);
            for (int nxt : graph.get(course)) {
                indegree[nxt]--;
                if (indegree[nxt] == 0) queue.add(nxt);
            }
        }
        if (order.size() != numCourses) return new int[0];
        int[] result = new int[numCourses];
        for (int i = 0; i < numCourses; i++) result[i] = order.get(i);
        return result;
    }
}

