        System.out.println(isPalindromeFilter(s));
    }

    public static boolean isPalindromeFilter(String s) {
        List<Character> filtered = new ArrayList<>();
        for (char c : s.toCharArray()) {
            if (Character.isLetterOrDigit(c)) filtered.add(Character.toLowerCase(c));
        }
        for (int i = 0; i < filtered.size() / 2; i++) {
            if (!filtered.get(i).equals(filtered.get(filtered.size() - 1 - i))) return false;
        }
        return true;
    }
}

