def search_range_expand(nums, target):
    left, right = 0, len(nums) - 1
    found = -1
    while left <= right:
        mid = (left + right) // 2
        if nums[mid] == target:
            found = mid
            break
        if nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    if found == -1:
        return [-1, -1]
    first = found
    while first > 0 and nums[first - 1] == target:
        first -= 1
    last = found
    while last < len(nums) - 1 and nums[last + 1] == target:
        last += 1
    return [first, last]


