def search_range_binary(nums, target):
    def lower_bound():
        left, right = 0, len(nums)
        while left < right:
            mid = (left + right) // 2
            if nums[mid] < target:
                left = mid + 1
            else:
                right = mid
        return left

    def upper_bound():
        left, right = 0, len(nums)
        while left < right:
            mid = (left + right) // 2
            if nums[mid] <= target:
                left = mid + 1
            else:
                right = mid
        return left

    first = lower_bound()
    last = upper_bound() - 1
    if first == len(nums) or nums[first] != target:
        return [-1, -1]
    return [first, last]


