    }

    public static int maxProfitValleyPeak(int[] prices) {
        int profit = 0;
        int i = 0;
        int n = prices.length;
        while (i < n - 1) {
            while (i < n - 1 && prices[i + 1] <= prices[i]) i++;
            int valley = prices[i];
            while (i < n - 1 && prices[i + 1] >= prices[i]) i++;
            int peak = prices[i];
            profit += peak - valley;
        }
        return profit;
    }
}

