        private final int capacity;
        private final Map<Integer, int[]> store = new HashMap<>();
        private int clock;

        LRUCache(int capacity) {
            this.capacity = capacity;
        }

        int get(int key) {
            int[] entry = store.get(key);
            if (entry == null) {
                return -1;
            }
            entry[1] = ++clock;
            return entry[0];
        }

        void put(int key, int value) {
            store.put(key, new int[] {value, ++clock});
            if (store.size() > capacity) {
                int oldestKey = -1;
                int oldestStamp = Integer.MAX_VALUE;
                for (Map.Entry<Integer, int[]> entry : store.entrySet()) {
                    if (entry.getValue()[1] < oldestStamp) {
                        oldestStamp = entry.getValue()[1];
                        oldestKey = entry.getKey();
                    }
                }
                store.remove(oldestKey);
            }
        }
    }

