import java.util.HashMap;
import java.util.Map;

public class Main {
    public static boolean isValid(String s) {
        Map<Character, Character> pairs = new HashMap<>();
        pairs.put('(', ')');
        pairs.put('[', ']');
        pairs.put('{', '}');
        return parseAll(s, pairs);
    }

    private static boolean parseAll(String s, Map<Character, Character> pairs) {
        int index = 0;
        while (index < s.length()) {
            Result res = parseGroup(s, index, pairs);
            if (!res.ok) {
                return false;
            }
            index = res.index;
        }
        return true;
    }

    private static Result parseGroup(String s, int i, Map<Character, Character> pairs) {
        if (i >= s.length()) {
            return new Result(i, true);
        }
        char opener = s.charAt(i);
        if (!pairs.containsKey(opener)) {
            return new Result(i, false);
        }
        char closer = pairs.get(opener);
        i++;
        while (i < s.length() && pairs.containsKey(s.charAt(i))) {
            Result res = parseGroup(s, i, pairs);
            if (!res.ok) {
                return res;
            }
            i = res.index;
        }
        if (i >= s.length() || s.charAt(i) != closer) {
            return new Result(i, false);
        }
        return new Result(i + 1, true);
    }

    static class Result {
        int index;
        boolean ok;

        Result(int index, boolean ok) {
            this.index = index;
            this.ok = ok;
        }
    }

    public static void main(String[] args) {
        System.out.println(isValid("({[]})"));
        System.out.println(isValid("([)]"));
