def binary_search(nums, lo, hi, target):
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1


def search_rotated_pivot(nums, target):
    pivot = find_pivot(nums)
    if pivot == 0:
        return binary_search(nums, 0, len(nums) - 1, target)
    if target >= nums[0]:
        return binary_search(nums, 0, pivot - 1, target)
    return binary_search(nums, pivot, len(nums) - 1, target)


