        System.out.println(searchWithPivot(new int[]{4, 5, 6, 7, 0, 1, 2}, 0));
    }

    static int findPivot(int[] nums) {
        int lo = 0, hi = nums.length - 1;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (nums[mid] > nums[hi]) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    static int binarySearch(int[] nums, int lo, int hi, int target) {
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (nums[mid] == target) return mid;
            if (nums[mid] < target) lo = mid + 1;
            else hi = mid - 1;
        }
        return -1;
    }

    static int searchWithPivot(int[] nums, int target) {
        int pivot = findPivot(nums);
        if (pivot == 0) return binarySearch(nums, 0, nums.length - 1, target);
        if (target >= nums[0]) return binarySearch(nums, 0, pivot - 1, target);
        return binarySearch(nums, pivot, nums.length - 1, target);
    }
}

