public class Main {
    public static void main(String[] args) {
        System.out.println(productExceptSelfLR(new int[]{1, 2, 3, 4}));
    }

    static List<Integer> productExceptSelfLR(int[] nums) {
        int n = nums.length;
        int[] left = new int[n];
        int[] right = new int[n];
        Arrays.fill(left, 1);
        Arrays.fill(right, 1);
        for (int i = 1; i < n; i++) left[i] = left[i - 1] * nums[i - 1];
        for (int i = n - 2; i >= 0; i--) right[i] = right[i + 1] * nums[i + 1];
        List<Integer> result = new ArrayList<>();
        for (int i = 0; i < n; i++) result.add(left[i] * right[i]);
        return result;
    }
}

