    lo = 0
    hi = len(nums) - 1
    while lo <= hi:
        pivot_index = partition(lo, hi)
        if pivot_index == target:
            return nums[pivot_index]
        if pivot_index < target:
            lo = pivot_index + 1
        else:
            hi = pivot_index - 1
