        nums[a] = nums[b];
        nums[b] = tmp;
    }

    static int partition(int[] nums, int lo, int hi) {
        int pivot = nums[hi];
        int i = lo;
        for (int j = lo; j < hi; j++) {
            if (nums[j] >= pivot) {
                swap(nums, i, j);
                i++;
            }
        }
        swap(nums, i, hi);
        return i;
    }

    static int findKthLargestQuickselect(int[] nums, int k) {
        int target = k - 1;
        int lo = 0, hi = nums.length - 1;
        while (lo <= hi) {
            int pivotIndex = partition(nums, lo, hi);
            if (pivotIndex == target) return nums[pivotIndex];
            if (pivotIndex < target) lo = pivotIndex + 1;
            else hi = pivotIndex - 1;
        }
        return -1;
    }
}

