    if (head == null) return null;
    Deque<ListNode> stack = new ArrayDeque<>();
    while (head != null) {
        stack.push(head);
        head = head.next;
    }
    ListNode newHead = stack.pop();
    ListNode cur = newHead;
    while (!stack.isEmpty()) {
        cur.next = stack.pop();
        cur = cur.next;
    }
    cur.next = null;
    return newHead;
}

