    if (memo.containsKey(k)) {
        return memo.get(k);
    }
    List<String> result = new ArrayList<>();
    for (int i = 0; i < k; i++) {
        for (String left : solve(i, memo)) {
            for (String right : solve(k - 1 - i, memo)) {
                result.add("(" + left + ")" + right);
            }
        }
    }
    memo.put(k, result);
    return result;
}

