public class Main {

static List<Integer> maxSlidingWindow(int[] nums, int k) {
    int n = nums.length;
    int[] left = new int[n];
    int[] right = new int[n];
    for (int i = 0; i < n; i++) {
        if (i % k == 0) {
            left[i] = nums[i];
        } else {
            left[i] = Math.max(left[i - 1], nums[i]);
