        res = new ArrayList<>();
        backtrack(new ArrayList<>(), new boolean[nums.length]);
        System.out.println(res);
    }

    static void backtrack(List<Integer> path, boolean[] used) {
        if (path.size() == nums.length) {
            res.add(new ArrayList<>(path));
            return;
        }
        for (int i = 0; i < nums.length; i++) {
            if (used[i]) continue;
            used[i] = true;
            path.add(nums[i]);
            backtrack(path, used);
