        Deque<TreeNode> stack = new ArrayDeque<>();
        Deque<Boolean> visited = new ArrayDeque<>();
        stack.push(root);
        visited.push(false);
        Map<TreeNode, Integer> gain = new IdentityHashMap<>();
        while (!stack.isEmpty()) {
