                int left = Math.max(gain.getOrDefault(node.left, 0), 0);
                int right = Math.max(gain.getOrDefault(node.right, 0), 0);
                best = Math.max(best, left + node.val + right);
                gain.put(node, node.val + Math.max(left, right));
            } else {
                stack.push(node);
                visited.push(true);
                if (node.right != null) { stack.push(node.right); visited.push(false); }
                if (node.left != null) { stack.push(node.left); visited.push(false); }
            }
        }
        return best;
    }

