import java.util.*;

class Main {
    static List<String> findWords(char[][] board, String[] words) {
        List<String> result = new ArrayList<>();
        for (String w : words)
            if (exists(board, w)) result.add(w);
        return result;
    }

    static boolean exists(char[][] board, String word) {
        for (int r = 0; r < board.length; r++)
            for (int c = 0; c < board[0].length; c++)
                if (search(board, r, c, word, 0)) return true;
        return false;
    }

    static boolean search(char[][] board, int r, int c, String word, int i) {
        if (i == word.length()) return true;
        if (r < 0 || r >= board.length || c < 0 || c >= board[0].length || board[r][c] != word.charAt(i)) return false;
        char save = board[r][c];
        board[r][c] = '#';
        int[][] dirs = {{1,0},{-1,0},{0,1},{0,-1}};
        for (int[] d : dirs) {
            if (search(board, r + d[0], c + d[1], word, i + 1)) {
                board[r][c] = save;
                return true;
            }
        }
        board[r][c] = save;
        return false;
    }

    public static void main(String[] args) {
