        nodes[4].left = nodes[7];
        nodes[4].right = nodes[8];

        System.out.println(lowestCommonAncestor(root, nodes[1], nodes[2]).val);
    }

    public static TreeNode lowestCommonAncestor(TreeNode root, TreeNode p, TreeNode q) {
        List<TreeNode> pathP = pathTo(root, p);
        List<TreeNode> pathQ = pathTo(root, q);
        TreeNode lca = root;
        int limit = Math.min(pathP.size(), pathQ.size());
        for (int i = 0; i < limit; i++) {
            if (pathP.get(i) == pathQ.get(i)) {
                lca = pathP.get(i);
            } else {
                break;
            }
        }
        return lca;
    }

    public static List<TreeNode> pathTo(TreeNode root, TreeNode target) {
        Deque<List<TreeNode>> stack = new ArrayDeque<>();
        List<TreeNode> start = new ArrayList<>();
        start.add(root);
        stack.push(start);
        while (!stack.isEmpty()) {
            List<TreeNode> path = stack.pop();
            TreeNode last = path.get(path.size() - 1);
            if (last == target) {
                return path;
            }
            if (last.right != null) {
                List<TreeNode> next = new ArrayList<>(path);
                next.add(last.right);
                stack.push(next);
            }
            if (last.left != null) {
                List<TreeNode> next = new ArrayList<>(path);
                next.add(last.left);
                stack.push(next);
            }
        }
        return new ArrayList<>();
    }
}

