        System.out.println(reversePopPush(123));
    }

    static int reversePopPush(int x) {
        int sign = x < 0 ? -1 : 1;
        long n = Math.abs((long) x);
        long result = 0;
        while (n > 0) {
            long digit = n % 10;
            if (result > (Integer.MAX_VALUE - digit) / 10) return 0;
            result = result * 10 + digit;
            n /= 10;
        }
        result *= sign;
        if (result > Integer.MAX_VALUE || result < Integer.MIN_VALUE) return 0;
        return (int) result;
    }
}

