public class Main {
    static Random rng = new Random(7L);

    public static void main(String[] args) {
        int[] weights = {1, 3};
        int[] counts = new int[2];
        for (int i = 0; i < 10000; i++) counts[pickBinary(weights)]++;
        System.out.println(Arrays.toString(counts));
    }

    static int pickBinary(int[] weights) {
        int n = weights.length;
        int[] prefix = new int[n];
        int acc = 0;
        for (int i = 0; i < n; i++) {
            acc += weights[i];
            prefix[i] = acc;
        }
        int r = 1 + rng.nextInt(acc);
        int lo = 0, hi = n - 1;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (prefix[mid] < r) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

