        return resolve(arr);
    }

    static List<Integer> resolve(List<Integer> arr) {
        for (int i = 1; i < arr.size(); i++) {
            int left = arr.get(i - 1);
            int right = arr.get(i);
            if (left > 0 && right < 0) {
                List<Integer> next = new ArrayList<>();
                next.addAll(arr.subList(0, i - 1));
                if (left != -right) next.add(left > -right ? left : right);
                next.addAll(arr.subList(i + 1, arr.size()));
                return resolve(next);
            }
        }
        return arr;
    }
}

