public class Main {
    public static void main(String[] args) {
        System.out.println(calculateTwoStacks("(1+(4+5+2)-3)+(6+8)"));
    }

    static int calculateTwoStacks(String s) {
        s = s.replace(" ", "");
        Deque<Character> ops = new ArrayDeque<>();
        Deque<Integer> nums = new ArrayDeque<>();
        int i = 0;
        while (i < s.length()) {
            char ch = s.charAt(i);
            if (Character.isDigit(ch)) {
                int num = 0;
                while (i < s.length() && Character.isDigit(s.charAt(i))) {
                    num = num * 10 + (s.charAt(i) - '0');
                    i++;
                }
                nums.addLast(num);
                continue;
            } else if (ch == '(') {
                ops.addLast(ch);
            } else if (ch == ')') {
                while (!ops.isEmpty() && ops.peekLast() != '(') apply(ops, nums);
                ops.pollLast();
            } else {
                while (!ops.isEmpty() && ops.peekLast() != '(') apply(ops, nums);
                ops.addLast(ch);
            }
            i++;
        }
        while (!ops.isEmpty()) apply(ops, nums);
        return nums.peekLast();
    }

    static void apply(Deque<Character> ops, Deque<Integer> nums) {
        char op = ops.pollLast();
        int b = nums.pollLast();
        int a = nums.pollLast();
        nums.addLast(op == '+' ? a + b : a - b);
    }
}

