public class Main {
    static class Node {
        int val;
        Node next;
        Node random;
        Node(int val) { this.val = val; }
    }

    public static void main(String[] args) {
        System.out.println(listRepr(copyInterleaved(buildSample())));
    }

    static Node buildSample() {
        Node n0 = new Node(7), n1 = new Node(13), n2 = new Node(11);
        Node n3 = new Node(10), n4 = new Node(1);
        n0.next = n1; n1.next = n2; n2.next = n3; n3.next = n4;
        n1.random = n0; n2.random = n4; n3.random = n2; n4.random = n0;
        return n0;
    }

    static List<List<Integer>> listRepr(Node head) {
        List<List<Integer>> out = new ArrayList<>();
        for (Node cur = head; cur != null; cur = cur.next) {
            out.add(Arrays.asList(cur.val, cur.random == null ? null : cur.random.val));
        }
        return out;
    }

    static Node copyInterleaved(Node head) {
        if (head == null) return null;
        Node cur = head;
        while (cur != null) {
            Node clone = new Node(cur.val);
            clone.next = cur.next;
            cur.next = clone;
            cur = clone.next;
        }
        cur = head;
        while (cur != null) {
            if (cur.random != null) cur.next.random = cur.random.next;
            cur = cur.next.next;
        }
        Node newHead = head.next;
        cur = head;
        while (cur != null) {
            Node clone = cur.next;
            cur.next = clone.next;
            if (clone.next != null) clone.next = clone.next.next;
            cur = cur.next;
        }
        return newHead;
    }
}

