        return n0;
    }

    static List<List<Integer>> listRepr(Node head) {
        List<List<Integer>> out = new ArrayList<>();
        for (Node cur = head; cur != null; cur = cur.next) {
            out.add(Arrays.asList(cur.val, cur.random == null ? null : cur.random.val));
        }
        return out;
    }

    static Node copyRecursive(Node head) {
        return copyRecursive(head, new HashMap<>());
    }

    static Node copyRecursive(Node head, Map<Node, Node> memo) {
        if (head == null) return null;
        if (memo.containsKey(head)) return memo.get(head);
        Node clone = new Node(head.val);
        memo.put(head, clone);
        clone.next = copyRecursive(head.next, memo);
        clone.random = copyRecursive(head.random, memo);
        return clone;
    }
}

