        int[] h = Arrays.copyOf(heights, n + 1);
        Deque<Integer> stack = new ArrayDeque<>();
        int maxArea = 0;
        for (int i = 0; i <= n; i++) {
            while (!stack.isEmpty() && h[stack.peekLast()] >= h[i]) {
                int height = h[stack.pollLast()];
                int width = stack.isEmpty() ? i : i - stack.peekLast() - 1;
                maxArea = Math.max(maxArea, height * width);
            }
            stack.addLast(i);
        }
        return maxArea;
    }
}

