    static int solve(int[] heights, int lo, int hi) {
        if (lo > hi) return 0;
        int minIndex = lo;
        for (int i = lo; i <= hi; i++) {
            if (heights[i] < heights[minIndex]) minIndex = i;
        }
        int area = heights[minIndex] * (hi - lo + 1);
        return Math.max(area, Math.max(solve(heights, lo, minIndex - 1), solve(heights, minIndex + 1, hi)));
    }
}

