def my_atoi_state_machine(s):
    index = 0
    length = len(s)
    while index < length and s[index] == ' ':
        index += 1
    if index == length:
        return 0
    sign = 1
    if s[index] == '+' or s[index] == '-':
        if s[index] == '-':
            sign = -1
        index += 1
    limit = 2**31 - 1
    value = 0
    while index < length and s[index].isdigit():
        digit = int(s[index])
        if value > (limit - digit) // 10:
            return limit if sign == 1 else -2**31
        value = value * 10 + digit
        index += 1
    return sign * value

