def binary_search(nums, target):
    low = 0
    high = len(nums) - 1
    while low <= high:
        mid = (low + high) // 2
        if nums[mid] == target:
            return True
        if nums[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return False


def intersection_binary(nums1, nums2):
    nums1.sort()
    result = []
    for x in set(nums2):
        if binary_search(nums1, x):
            result.append(x)
    return result

