        self.stack = [nested_list]
        self.indexes = [0]
        self._advance()

    def _advance(self):
        while self.stack:
            items = self.stack[-1]
            index = self.indexes[-1]
            if index >= len(items):
                self.stack.pop()
                self.indexes.pop()
                continue
            item = items[index]
            if isinstance(item, int):
                return
            self.indexes[-1] += 1
            self.stack.append(item)
            self.indexes.append(0)

    def has_next(self):
        return bool(self.stack)

    def next(self):
        items = self.stack[-1]
        value = items[self.indexes[-1]]
        self.indexes[-1] += 1
        self._advance()
        return value

