    static class NestedListIteratorLazy {
        Deque<List<NestedInteger>> stack = new ArrayDeque<>();
        Deque<Integer> indexes = new ArrayDeque<>();

        NestedListIteratorLazy(List<NestedInteger> nested) {
            stack.push(nested);
            indexes.push(0);
            advance();
        }

        void advance() {
            while (!stack.isEmpty()) {
                List<NestedInteger> items = stack.peek();
                int index = indexes.peek();
                if (index >= items.size()) {
                    stack.pop();
                    indexes.pop();
                    continue;
