                indexes.push(indexes.pop() + 1);
                stack.push(item.items);
                indexes.push(0);
            }
        }

        boolean hasNext() {
            return !stack.isEmpty();
        }

        int next() {
            List<NestedInteger> items = stack.peek();
            int value = items.get(indexes.peek()).value;
