class Main {
    static int boxIndex(int r, int c) {
        return (r / 3) * 3 + c / 3;
    }

    static boolean backtrack(char[][] board, Set<Character>[] rows, Set<Character>[] cols,
                             Set<Character>[] boxes, List<int[]> empty, int idx) {
        if (idx == empty.size()) return true;
        int r = empty.get(idx)[0];
        int c = empty.get(idx)[1];
        int b = boxIndex(r, c);
        for (char d = '1'; d <= '9'; d++) {
            if (rows[r].contains(d) || cols[c].contains(d) || boxes[b].contains(d)) continue;
            board[r][c] = d;
            rows[r].add(d);
            cols[c].add(d);
            boxes[b].add(d);
            if (backtrack(board, rows, cols, boxes, empty, idx + 1)) return true;
            rows[r].remove(d);
            cols[c].remove(d);
            boxes[b].remove(d);
            board[r][c] = '.';
        }
        return false;
    }

    static void solveSudoku(char[][] board) {
        Set<Character>[] rows = new HashSet[9];
        Set<Character>[] cols = new HashSet[9];
        Set<Character>[] boxes = new HashSet[9];
