class Main {
    static boolean solve(char[][] board, int[] rows, int[] cols, int[] boxes, List<int[]> empty, int idx) {
        if (idx == empty.size()) return true;
        int r = empty.get(idx)[0];
        int c = empty.get(idx)[1];
        int b = (r / 3) * 3 + c / 3;
        int used = rows[r] | cols[c] | boxes[b];
        for (int d = 1; d <= 9; d++) {
            int bit = 1 << d;
            if ((used & bit) != 0) continue;
            board[r][c] = (char) ('0' + d);
            rows[r] |= bit;
            cols[c] |= bit;
            boxes[b] |= bit;
            if (solve(board, rows, cols, boxes, empty, idx + 1)) return true;
            rows[r] ^= bit;
            cols[c] ^= bit;
            boxes[b] ^= bit;
            board[r][c] = '.';
        }
        return false;
    }

