class Main {
    static boolean solveMRV(char[][] board, Set<Character>[] rows, Set<Character>[] cols,
                            Set<Character>[] boxes) {
        int bestR = -1, bestC = -1;
        List<Character> bestCands = null;
        for (int r = 0; r < 9; r++) {
            for (int c = 0; c < 9; c++) {
                if (board[r][c] != '.') continue;
                int b = (r / 3) * 3 + c / 3;
                List<Character> cands = new ArrayList<>();
                for (char d = '1'; d <= '9'; d++)
                    if (!rows[r].contains(d) && !cols[c].contains(d) && !boxes[b].contains(d))
                        cands.add(d);
                if (cands.isEmpty()) return false;
                if (bestCands == null || cands.size() < bestCands.size()) {
                    bestR = r;
                    bestC = c;
                    bestCands = cands;
                }
            }
        }
        if (bestR == -1) return true;
        int b = (bestR / 3) * 3 + bestC / 3;
        for (char d : bestCands) {
            board[bestR][bestC] = d;
            rows[bestR].add(d);
            cols[bestC].add(d);
            boxes[b].add(d);
            if (solveMRV(board, rows, cols, boxes)) return true;
            rows[bestR].remove(d);
            cols[bestC].remove(d);
            boxes[b].remove(d);
            board[bestR][bestC] = '.';
        }
        return false;
    }

    static void solveSudoku(char[][] board) {
        Set<Character>[] rows = new HashSet[9];
        Set<Character>[] cols = new HashSet[9];
        Set<Character>[] boxes = new HashSet[9];
