                if (board[r][c] != '.') {
                    rows[r].add(board[r][c]);
                    cols[c].add(board[r][c]);
                    boxes[(r / 3) * 3 + c / 3].add(board[r][c]);
                }
        solveMRV(board, rows, cols, boxes);
    }

