class LFUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.values = {}
        self.freqs = {}
        self.buckets = {}
        self.min_freq = 0

    def get(self, key):
        if key not in self.values:
            return -1
        self._increase(key)
        return self.values[key]

    def put(self, key, value):
        if self.capacity <= 0:
            return
        if key in self.values:
            self.values[key] = value
            self._increase(key)
            return
        if len(self.values) >= self.capacity:
            self._evict()
        self.values[key] = value
        self.freqs[key] = 1
        self.buckets.setdefault(1, {}).setdefault(key, None)
        self.min_freq = 1

    def _increase(self, key):
        freq = self.freqs[key]
        del self.buckets[freq][key]
        if not self.buckets[freq]:
            del self.buckets[freq]
            if freq == self.min_freq:
                self.min_freq += 1
        self.freqs[key] = freq + 1
        self.buckets.setdefault(freq + 1, {}).setdefault(key, None)

    def _evict(self):
        bucket = self.buckets[self.min_freq]
        victim = next(iter(bucket))
        del bucket[victim]
        if not bucket:
            del self.buckets[self.min_freq]
        del self.values[victim]
        del self.freqs[victim]

