class Main {
    static int capacity;
    static int minFreq;
    static Map<Integer, Integer> values = new HashMap<>();
    static Map<Integer, Integer> freqs = new HashMap<>();
    static Map<Integer, LinkedHashSet<Integer>> buckets = new HashMap<>();

    static int get(int key) {
        if (!values.containsKey(key)) return -1;
        increase(key);
        return values.get(key);
    }

    static void put(int key, int value) {
        if (capacity <= 0) return;
        if (values.containsKey(key)) {
            values.put(key, value);
            increase(key);
            return;
        }
        if (values.size() >= capacity) evict();
        values.put(key, value);
        freqs.put(key, 1);
        buckets.computeIfAbsent(1, k -> new LinkedHashSet<>()).add(key);
        minFreq = 1;
    }

    static void increase(int key) {
        int f = freqs.get(key);
        buckets.get(f).remove(key);
        if (buckets.get(f).isEmpty()) {
            buckets.remove(f);
            if (f == minFreq) minFreq++;
        }
        freqs.put(key, f + 1);
        buckets.computeIfAbsent(f + 1, k -> new LinkedHashSet<>()).add(key);
    }

    static void evict() {
        LinkedHashSet<Integer> bucket = buckets.get(minFreq);
        int victim = bucket.iterator().next();
        bucket.remove(victim);
        if (bucket.isEmpty()) buckets.remove(minFreq);
        values.remove(victim);
        freqs.remove(victim);
    }

    public static void main(String[] args) {
        capacity = 2;
        put(1, 1);
        put(2, 2);
        System.out.println(get(1));
