    static Map<Integer, Integer> freqs = new HashMap<>();
    static PriorityQueue<long[]> heap = new PriorityQueue<>((a, b) -> {
        if (a[0] != b[0]) return Long.compare(a[0], b[0]);
        if (a[1] != b[1]) return Long.compare(a[1], b[1]);
        return Long.compare(a[2], b[2]);
    });

    static int get(int key) {
        if (!values.containsKey(key)) return -1;
        bump(key);
        return values.get(key);
    }

    static void bump(int key) {
        tick++;
        freqs.put(key, freqs.get(key) + 1);
        heap.offer(new long[]{freqs.get(key), tick, key});
    }

    static void put(int key, int value) {
        if (capacity <= 0) return;
        if (values.containsKey(key)) {
            values.put(key, value);
            bump(key);
            return;
        }
        if (values.size() >= capacity) evict();
        values.put(key, value);
        freqs.put(key, 1);
        tick++;
        heap.offer(new long[]{1, tick, key});
    }

    static void evict() {
        while (true) {
            long[] top = heap.poll();
            int key = (int) top[2];
            int freq = (int) top[0];
            if (values.containsKey(key) && freqs.get(key) == freq) {
                values.remove(key);
                freqs.remove(key);
                return;
            }
        }
    }

