import java.util.*;

class Main {
    static int[] starts;
    static int[] ends;
    static int[] profits;
    static int[] memo;
    static int n;

    static int jobScheduling(int[] startTime, int[] endTime, int[] profit) {
        n = startTime.length;
        int[][] jobs = new int[n][3];
        for (int i = 0; i < n; i++) {
            jobs[i][0] = startTime[i];
            jobs[i][1] = endTime[i];
            jobs[i][2] = profit[i];
        }
        Arrays.sort(jobs, (a, b) -> Integer.compare(a[0], b[0]));
        starts = new int[n];
        ends = new int[n];
        profits = new int[n];
        for (int i = 0; i < n; i++) {
            starts[i] = jobs[i][0];
            ends[i] = jobs[i][1];
            profits[i] = jobs[i][2];
        }
        memo = new int[n];
        Arrays.fill(memo, -1);
        return dp(0);
    }

    static int dp(int i) {
        if (i >= n) return 0;
        if (memo[i] != -1) return memo[i];
        int skip = dp(i + 1);
        int j = lowerBound(starts, ends[i]);
        int take = profits[i] + dp(j);
        memo[i] = Math.max(skip, take);
        return memo[i];
    }

    static int lowerBound(int[] arr, int target) {
        int lo = 0, hi = arr.length;
        while (lo < hi) {
            int mid = (lo + hi) / 2;
            if (arr[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    public static void main(String[] args) {
        System.out.println(jobScheduling(
                new int[]{1, 2, 3, 3},
                new int[]{3, 4, 5, 6},
                new int[]{50, 10, 40, 70}));
    }
}

