def job_scheduling_sweep(start_time, end_time, profit):
    times = sorted(set(start_time + end_time))
    index = {t: i for i, t in enumerate(times)}
    by_end = {}
    for s, e, p in zip(start_time, end_time, profit):
        by_end.setdefault(e, []).append((s, p))
    best = [0] * len(times)
    for i, t in enumerate(times):
        if i > 0:
            best[i] = best[i - 1]
        for s, p in by_end.get(t, []):
            candidate = best[index[s]] + p
            if candidate > best[i]:
                best[i] = candidate
    return best[-1]

