import java.util.*;

public class Main {
    public static List<List<String>> solveNQueens(int n) {
        List<List<String>> solutions = new ArrayList<>();
        backtrack(0, n, 0, 0, 0, new ArrayList<>(), solutions);
        return solutions;
    }

    private static void backtrack(int row, int n, int cols, int diag1, int diag2,
                                  List<Integer> queens, List<List<String>> solutions) {
        if (row == n) {
            List<String> board = new ArrayList<>();
            for (int r = 0; r < n; r++) {
                char[] line = new char[n];
                Arrays.fill(line, '.');
                line[queens.get(r)] = 'Q';
                board.add(new String(line));
            }
            solutions.add(board);
            return;
        }
        int available = ((1 << n) - 1) & ~(cols | diag1 | diag2);
        while (available != 0) {
            int bit = available & -available;
            available -= bit;
            int col = Integer.numberOfTrailingZeros(bit);
            queens.add(col);
            backtrack(row + 1, n, cols | bit, (diag1 | bit) << 1, (diag2 | bit) >> 1, queens, solutions);
            queens.remove(queens.size() - 1);
        }
    }

    public static void main(String[] args) {
        for (List<String> solution : solveNQueens(4)) {
            for (String line : solution) System.out.println(line);
            System.out.println();
        }
    }
}

