def reorganize_string(s):
    counter = Counter(s)
    heap = []
    for char, count in counter.items():
        heapq.heappush(heap, (-count, char))

    result = []
    prev_char = None
    prev_count = 0
    while heap:
        neg_count, char = heapq.heappop(heap)
        count = -neg_count
        result.append(char)
        if prev_char is not None and prev_count > 0:
            heapq.heappush(heap, (-prev_count, prev_char))
        prev_char = char
        prev_count = count - 1

    if prev_count > 0:
        return ""
    return "".join(result)


