from collections import deque


class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right


def diameter_of_binary_tree(root):
    if root is None:
        return 0

    parents = {}

    def build_parents(node, parent):
        if node is None:
            return
        parents[node] = parent
        build_parents(node.left, node)
        build_parents(node.right, node)

    build_parents(root, None)

    def bfs(start):
        queue = deque([start])
        dist = {start: 0}
        farthest_node = start
        max_dist = 0
        while queue:
            node = queue.popleft()
            for neighbor in (node.left, node.right, parents.get(node)):
                if neighbor is not None and neighbor not in dist:
                    dist[neighbor] = dist[node] + 1
                    queue.append(neighbor)
                    if dist[neighbor] > max_dist:
                        max_dist = dist[neighbor]
                        farthest_node = neighbor
        return farthest_node, max_dist

    far_a, _ = bfs(root)
    _, diameter = bfs(far_a)
    return diameter


if __name__ == "__main__":
    root = TreeNode(1,
                    TreeNode(2, TreeNode(4), TreeNode(5)),
                    TreeNode(3))
