import java.util.*;

public class Main {
    static class TreeNode {
        int val;
        TreeNode left, right;
        TreeNode(int v) { val = v; }
        TreeNode(int v, TreeNode l, TreeNode r) { val = v; left = l; right = r; }
    }

    static class BfsResult {
        TreeNode node;
        int dist;
    }

    static int diameterOfBinaryTree(TreeNode root) {
        if (root == null) return 0;
        Map<TreeNode, TreeNode> parents = new HashMap<>();
        buildParents(root, null, parents);
        TreeNode farA = bfs(root, parents).node;
        return bfs(farA, parents).dist;
    }

    static void buildParents(TreeNode node, TreeNode parent, Map<TreeNode, TreeNode> parents) {
        if (node == null) return;
        parents.put(node, parent);
        buildParents(node.left, node, parents);
        buildParents(node.right, node, parents);
    }

    static BfsResult bfs(TreeNode start, Map<TreeNode, TreeNode> parents) {
        Deque<TreeNode> queue = new ArrayDeque<>();
        Map<TreeNode, Integer> dist = new HashMap<>();
        queue.add(start);
        dist.put(start, 0);
        TreeNode farNode = start;
        int maxDist = 0;
        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();
            for (TreeNode nb : new TreeNode[]{node.left, node.right, parents.get(node)}) {
                if (nb != null && !dist.containsKey(nb)) {
                    dist.put(nb, dist.get(node) + 1);
                    queue.add(nb);
                    if (dist.get(nb) > maxDist) {
                        maxDist = dist.get(nb);
                        farNode = nb;
                    }
                }
            }
        }
        BfsResult res = new BfsResult();
        res.node = farNode;
        res.dist = maxDist;
        return res;
    }

    public static void main(String[] args) {
        TreeNode root = new TreeNode(1,
                new TreeNode(2, new TreeNode(4), new TreeNode(5)),
                new TreeNode(3));
        System.out.println(diameterOfBinaryTree(root));
    }
}

