public class Main {
    public static void main(String[] args) {
        int[][] grid = {{1, 3, 1}, {1, 5, 1}, {4, 2, 1}};
        System.out.println(minPathSum(grid));
    }

    static int minPathSum(int[][] grid) {
        int rows = grid.length, cols = grid[0].length;
        int[][] distances = new int[rows][cols];
        for (int[] row : distances) Arrays.fill(row, Integer.MAX_VALUE);
        distances[0][0] = grid[0][0];
        PriorityQueue<int[]> heap = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        heap.add(new int[]{grid[0][0], 0, 0});
        int[][] dirs = {{1, 0}, {0, 1}};
        while (!heap.isEmpty()) {
            int[] cur = heap.poll();
            int cost = cur[0], r = cur[1], c = cur[2];
            if (r == rows - 1 && c == cols - 1) return cost;
            for (int[] d : dirs) {
                int nr = r + d[0], nc = c + d[1];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                    int newCost = cost + grid[nr][nc];
                    if (newCost < distances[nr][nc]) {
                        distances[nr][nc] = newCost;
                        heap.add(new int[]{newCost, nr, nc});
                    }
                }
            }
        }
        return -1;
    }
}

