public class Main {
    private String s;
    private int i;

    public int calculate(String expr) {
        s = expr.replace(" ", "");
        i = 0;
        return parseExpr();
    }

    private int parseExpr() {
        int val = parseTerm();
        while (i < s.length() && (s.charAt(i) == '+' || s.charAt(i) == '-')) {
            char op = s.charAt(i++);
            int rhs = parseTerm();
            val = op == '+' ? val + rhs : val - rhs;
        }
        return val;
    }

    private int parseTerm() {
        int val = parseFactor();
        while (i < s.length() && (s.charAt(i) == '*' || s.charAt(i) == '/')) {
            char op = s.charAt(i++);
            int rhs = parseFactor();
            val = op == '*' ? val * rhs : val / rhs;
        }
        return val;
    }

    private int parseFactor() {
        if (s.charAt(i) == '(') {
            i++;
            int val = parseExpr();
            i++;
            return val;
        }
        int start = i;
        while (i < s.length() && Character.isDigit(s.charAt(i))) i++;
        return Integer.parseInt(s.substring(start, i));
