    vals = []
    i = 0
    n = len(s)
    prec = {"+": 1, "-": 1, "*": 2, "/": 2}

    def apply_op():
        b = vals.pop()
        a = vals.pop()
        op = ops.pop()
        if op == "+":
            vals.append(a + b)
        elif op == "-":
            vals.append(a - b)
        elif op == "*":
            vals.append(a * b)
        else:
            vals.append(int(a / b))

    while i < n:
        c = s[i]
        if c == " ":
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            vals.append(int(s[i:j]))
            i = j
            continue
        if c == "(":
            ops.append(c)
        elif c == ")":
            while ops and ops[-1] != "(":
                apply_op()
            ops.pop()
        else:
            while ops and ops[-1] != "(" and prec[ops[-1]] >= prec[c]:
                apply_op()
            ops.append(c)
        i += 1
    while ops:
        apply_op()
    return vals[0]


