import java.util.*;

public class Main {
    private static int applyOp(int a, int b, char op) {
        if (op == '+') return a + b;
        if (op == '-') return a - b;
        if (op == '*') return a * b;
        return a / b;
    }

    public static int calculate(String s) {
        Deque<Character> ops = new ArrayDeque<>();
        Deque<Integer> vals = new ArrayDeque<>();
        Map<Character, Integer> prec = new HashMap<>();
        prec.put('+', 1);
        prec.put('-', 1);
        prec.put('*', 2);
        prec.put('/', 2);
        int i = 0, n = s.length();
        while (i < n) {
            char c = s.charAt(i);
            if (c == ' ') { i++; continue; }
            if (Character.isDigit(c)) {
                int j = i;
                while (j < n && Character.isDigit(s.charAt(j))) j++;
                vals.push(Integer.parseInt(s.substring(i, j)));
                i = j;
                continue;
            }
            if (c == '(') {
                ops.push(c);
            } else if (c == ')') {
                while (ops.peek() != '(') {
                    vals.push(applyOp(vals.pop(), vals.pop(), ops.pop()));
                }
                ops.pop();
            } else {
                while (!ops.isEmpty() && ops.peek() != '(' && prec.get(ops.peek()) >= prec.get(c)) {
                    vals.push(applyOp(vals.pop(), vals.pop(), ops.pop()));
                }
                ops.push(c);
            }
            i++;
        }
        while (!ops.isEmpty()) {
            vals.push(applyOp(vals.pop(), vals.pop(), ops.pop()));
        }
        return vals.peek();
    }

    public static void main(String[] args) {
        System.out.println(calculate("2*(5+5*2)/3+(6/2+8)"));
    }
}

import java.util.*;

public class Main {
    private static int evalSimple(List<String> tokens) {
        List<Integer> vals = new ArrayList<>();
        List<Character> ops = new ArrayList<>();
        vals.add(Integer.parseInt(tokens.get(0)));
        int idx = 1;
        while (idx < tokens.size()) {
            char op = tokens.get(idx).charAt(0);
            int num = Integer.parseInt(tokens.get(idx + 1));
            if (op == '*' || op == '/') {
                int last = vals.remove(vals.size() - 1);
                vals.add(op == '*' ? last * num : last / num);
            } else {
                ops.add(op);
                vals.add(num);
            }
            idx += 2;
        }
        int total = vals.get(0);
        for (int k = 0; k < ops.size(); k++) {
            total = ops.get(k) == '+' ? total + vals.get(k + 1) : total - vals.get(k + 1);
        }
        return total;
    }

    public static int calculate(String s) {
        String[] parts = s.replace(" ", "").split("(?<=\\D)|(?=\\D)");
        List<String> tokens = new ArrayList<>(Arrays.asList(parts));
        while (tokens.contains("(")) {
            int close = tokens.indexOf(")");
            int open = -1;
            for (int k = close - 1; k >= 0; k--) {
                if (tokens.get(k).equals("(")) {
                    open = k;
                    break;
                }
            }
            int inner = evalSimple(tokens.subList(open + 1, close));
            List<String> rebuilt = new ArrayList<>(tokens.subList(0, open));
            rebuilt.add(String.valueOf(inner));
            rebuilt.addAll(tokens.subList(close + 1, tokens.size()));
            tokens = rebuilt;
        }
        return evalSimple(tokens);
    }

    public static void main(String[] args) {
        System.out.println(calculate("2*(5+5*2)/3+(6/2+8)"));
    }
}

