        int n;
        int[][] marks = new int[2][4]; // [player][rows|cols|diag|anti]

        TicTacToe(int n) {
            this.n = n;
        }

        int move(int row, int col, int player) {
            int p = player - 1;
            marks[p][0] |= 1 << row;
            marks[p][1] |= 1 << col;
