import java.util.*;

public class Main {
    static int total;
    static Map<String, List<String>> graph;

    static List<String> findItinerary(List<List<String>> tickets) {
        graph = new HashMap<>();
        for (List<String> t : tickets) {
            graph.computeIfAbsent(t.get(0), k -> new ArrayList<>()).add(t.get(1));
        }
        for (List<String> lst : graph.values()) Collections.sort(lst);
        total = tickets.size();
        List<String> path = new ArrayList<>();
        path.add("JFK");
        return dfs("JFK", 0, path);
    }

    static List<String> dfs(String airport, int used, List<String> path) {
        if (used == total) return new ArrayList<>(path);
        List<String> dests = graph.get(airport);
        for (int i = 0; dests != null && i < dests.size(); i++) {
            String nxt = dests.remove(i);
            path.add(nxt);
            List<String> res = dfs(nxt, used + 1, path);
            if (res != null) return res;
            path.remove(path.size() - 1);
            dests.add(i, nxt);
        }
        return null;
    }

